const WEIGHTS = { ping: 30, jitter: 20, loss: 20, down: 20, up: 10 };
export const regionById = (id) => REGIONS.find((r) => r.id === id);
export const connectionById = (id) => CONNECTION_TYPES.find((c) => c.id === id);
